/**
 * PETMOL Recommendations — editorial picks with official Amazon Associates US
 * Special Links.
 *
 * HARD RULES (see the mission brief):
 *  - `affiliateUrl` is the EXACT amzn.to Special Link generated by the
 *    Amazon SiteStripe on the PETMOL Associates account. It is NEVER rebuilt,
 *    never gets a manual `?tag=`, never runs through `features/commerce/amazon.ts`
 *    (that module is for amazon.com.br and is unrelated to this page), and is
 *    never wrapped in an internal redirect. The public `href` IS this string.
 *  - No prices, ratings, review counts, stock, shipping or "best price" claims.
 *  - No Amazon images, no scraping, no Product Advertising API.
 *  - Products whose destination could not be identified with confidence are
 *    kept here, flagged `needsEditorialMetadata`, and reported for a human to
 *    fill in. Their title/blurb are deliberately generic — nothing invented.
 *
 * Store / Tracking ID on the account: petmol07-20 (embedded by Amazon inside
 * each Special Link — do not touch).
 */

export type RecommendationCategory =
  | 'for-pets'
  | 'home-with-pets'
  | 'cleaning-organization'
  | 'smart-home-technology'
  | 'travel-outdoors'
  | 'petmol-finds';

export interface RecommendationCategoryMeta {
  id: RecommendationCategory;
  label: string;
  description: string;
}

