/** Categories that actually have at least one pick, in display order. */
export function getPopulatedCategories(): RecommendationCategoryMeta[] {
  return RECOMMENDATION_CATEGORIES.filter((c) =>
    RECOMMENDATIONS.some((r) => r.category === c.id),
  );
}

export function getRecommendationsByCategory(category: RecommendationCategory): Recommendation[] {
  return RECOMMENDATIONS.filter((r) => r.category === category);
}

/** Links that still need a human to confirm the product. */
export function getRecommendationsNeedingMetadata(): Recommendation[] {
  return RECOMMENDATIONS.filter((r) => r.needsEditorialMetadata);
}

